import{_ as n,o as h,c as i,a5 as e}from"./chunks/framework.CsGesDJn.js";const u=JSON.parse('{"title":"FR 3.10.3 — BrandHub System Health Monitoring","description":"","frontmatter":{},"headers":[],"relativePath":"feature/admin-management/system-health/spec.md","filePath":"feature/admin-management/system-health/spec.md"}'),a={name:"feature/admin-management/system-health/spec.md"};function c(r,t,o,g,l,s){return h(),i("div",null,[...t[0]||(t[0]=[e('<h1 id="fr-3-10-3-—-brandhub-system-health-monitoring" tabindex="-1">FR 3.10.3 — BrandHub System Health Monitoring <a class="header-anchor" href="#fr-3-10-3-—-brandhub-system-health-monitoring" aria-label="Permalink to &quot;FR 3.10.3 — BrandHub System Health Monitoring&quot;">​</a></h1><p>&gt; Đặc tả mục tiêu theo mẫu <code>to-spec</code>, tổng hợp từ yêu cầu đã trao đổi và mã nguồn đã đọc. Người dùng đã xác nhận phạm vi kiểm thử và chọn chỉ lưu tài liệu local. Chưa triển khai hoặc kiểm thử chức năng này trong BrandHub; không đăng issue.</p><h2 id="problem-statement" tabindex="-1">Problem Statement <a class="header-anchor" href="#problem-statement" aria-label="Permalink to &quot;Problem Statement&quot;">​</a></h2><p>ADMIN của BrandHub cần biết các máy đang chạy hệ thống tiêu tốn bao nhiêu tài nguyên, còn liên lạc được không, và từng microservice, container, database hay endpoint nghiệp vụ có đáp ứng đúng hay không. Hiện các repo và cấu hình deployment chưa cung cấp một màn hình giám sát hợp nhất đáp ứng đầy đủ yêu cầu này.</p><p>Một repo không tương ứng với một server: nhiều service có thể chạy cùng EC2, một service có thể có nhiều replica trên các máy khác nhau. Server còn gửi heartbeat không chứng minh mọi ứng dụng trên đó khỏe; container Running không chứng minh ứng dụng sẵn sàng phục vụ. Thiếu dữ liệu hoặc lỗi chính hệ thống giám sát cũng không đủ để kết luận đối tượng đã ngừng hoạt động.</p><p>VPS Monitor hiện tại là nguồn tham khảo cho collector tài nguyên và dashboard, không phải tính năng đã tích hợp BrandHub. Cần tận dụng mô hình tài khoản và quyền system ADMIN của BrandHub, đồng thời phân biệt rõ dữ liệu hiện tại, dữ liệu cũ và chưa có dữ liệu.</p><h2 id="solution" tabindex="-1">Solution <a class="header-anchor" href="#solution" aria-label="Permalink to &quot;Solution&quot;">​</a></h2><p>Cung cấp một trang <strong>Admin → System Health</strong> tại route <code>/admin/system-health</code>, gồm hai tab:</p><ul><li><strong>Servers:</strong> tên/IP, môi trường, service được triển khai, CPU, RAM, Disk, uptime, Online/Offline/Chưa có dữ liệu và lần nhận heartbeat cuối.</li><li><strong>Services &amp; Dependencies:</strong> health từng instance microservice, container, database và endpoint; trạng thái UP/DOWN/UNKNOWN, phạm vi kiểm tra, runtime state nếu có, độ trễ, thời điểm probe và lý do lỗi.</li></ul><p>Có bộ lọc môi trường và server; tab health bổ sung loại đối tượng và trạng thái. Thông tin chi tiết nguồn kiểm tra và kết quả gần nhất có thể mở trong panel tại cùng trang, không cần route chi tiết riêng.</p><p>Agent tài nguyên và collector health chạy nền ngay cả khi không có người mở trang. Trang admin chỉ đọc kết quả qua API được bảo vệ, không truy cập Docker/database trực tiếp và không khởi chạy probe. Chỉ giữ mẫu mới nhất, chưa cần lịch sử, biểu đồ hoặc hệ thống cảnh báo.</p><h2 id="user-stories" tabindex="-1">User Stories <a class="header-anchor" href="#user-stories" aria-label="Permalink to &quot;User Stories&quot;">​</a></h2><ol><li>As an ADMIN, I want mở System Health trong phần quản trị, so that tôi theo dõi hạ tầng BrandHub tại một nơi.</li><li>As an ADMIN, I want chỉ system ADMIN được truy cập dữ liệu giám sát, so that thông tin vận hành không bị lộ cho người dùng thông thường hoặc quản trị workspace.</li><li>As an ADMIN, I want xem tất cả server đã khai báo kể cả chưa có mẫu, so that tôi phát hiện máy chưa được kết nối giám sát.</li><li>As an ADMIN, I want xem tên, IP, môi trường và service chạy trên từng host, so that tôi nhận diện đúng máy cần xử lý.</li><li>As an ADMIN, I want một host chỉ xuất hiện một lần dù chạy nhiều repo, so that tôi không hiểu nhầm hoặc đếm trùng tài nguyên.</li><li>As an ADMIN, I want xem CPU, RAM và Disk theo phần trăm cùng uptime host, so that tôi đánh giá mức sử dụng tài nguyên gần nhất.</li><li>As an ADMIN, I want chỉ số không đọc được hiển thị dấu “—”, so that tôi không nhầm thiếu dữ liệu với mức sử dụng bằng 0.</li><li>As an ADMIN, I want biết thời điểm nhận heartbeat gần nhất, so that tôi đánh giá độ mới của trạng thái host.</li><li>As an ADMIN, I want phân biệt Online, Offline và Chưa có dữ liệu, so that tôi biết host còn liên lạc hay chưa từng báo cáo.</li><li>As an ADMIN, I want giữ mẫu cuối với nhãn Dữ liệu cũ khi host Offline, so that tôi có ngữ cảnh mà không nhầm đó là số liệu hiện tại.</li><li>As an ADMIN, I want host tự trở lại Online khi nhận heartbeat hợp lệ, so that tôi nhận biết kết nối đã phục hồi.</li><li>As an ADMIN, I want lọc theo môi trường và host, so that tôi tập trung vào deployment cần theo dõi.</li><li>As an ADMIN, I want xem health riêng từng instance service, so that tôi biết replica nào lỗi dù host vẫn Online.</li><li>As an ADMIN, I want phân biệt probe readiness và liveness, so that tôi hiểu chính xác kết quả đã chứng minh điều gì.</li><li>As an ADMIN, I want xem runtime state và Docker health riêng biệt, so that tôi không coi container Running là ứng dụng khỏe.</li><li>As an ADMIN, I want container đã khai báo nhưng bị dừng hoặc xóa vẫn xuất hiện, so that lỗi deployment không biến mất khỏi dashboard.</li><li>As an ADMIN, I want container chưa có healthcheck hiển thị UNKNOWN, so that hệ thống không tự tạo kết luận khỏe.</li><li>As an ADMIN, I want database được kiểm tra bằng kết nối xác thực và thao tác nhẹ, so that cổng mở không bị hiểu nhầm là database dùng được.</li><li>As an ADMIN, I want xem health dịch vụ managed mà không có CPU/RAM host giả, so that số liệu phản ánh đúng phạm vi quan sát.</li><li>As an ADMIN, I want kiểm tra một số endpoint nghiệp vụ đọc dữ liệu qua Gateway, so that tôi biết các luồng đọc được chọn có đáp ứng đúng hợp đồng.</li><li>As an ADMIN, I want kết quả HTTP được kiểm tra cả status lẫn nội dung mong đợi, so that trang lỗi trả 200 không bị báo UP.</li><li>As an ADMIN, I want xem thời điểm, độ trễ, collector và lý do lỗi của từng phép kiểm tra, so that tôi có thông tin để điều tra.</li><li>As an ADMIN, I want phân biệt target DOWN với collector lỗi hoặc mẫu stale, so that tôi không xử lý nhầm nguyên nhân.</li><li>As an ADMIN, I want một probe lỗi không làm mất kết quả các đối tượng khác, so that tôi vẫn quan sát được phần hệ thống còn lại.</li><li>As an ADMIN, I want xem từng replica kể cả khi có trạng thái tổng hợp, so that một instance khỏe không che khuất instance lỗi.</li><li>As an ADMIN, I want trạng thái health tự phục hồi sau probe thành công, so that dashboard phản ánh kết quả mới nhất.</li><li>As an ADMIN, I want dữ liệu tự làm mới khi trang đang hoạt động, so that tôi không phải tải lại thủ công.</li><li>As an ADMIN, I want bảng host và bảng health báo lỗi tải độc lập, so that một API lỗi không làm mất bảng còn cập nhật được.</li><li>As an ADMIN, I want ngừng nhận và hiển thị dữ liệu bảo vệ khi phiên hết hạn hoặc quyền bị thu hồi, so that quyền truy cập được thực thi đúng.</li><li>As an operator, I want khai báo host, target, collector và môi trường trước khi chạy, so that chỉ đối tượng được phép mới xuất hiện trong hệ thống.</li><li>As an operator, I want ID host ổn định qua lần redeploy container, so that triển khai lại ứng dụng không tạo server trùng.</li><li>As an operator, I want cấp ID mới khi thay máy và cập nhật ánh xạ service, so that dữ liệu máy cũ không bị gắn nhầm cho máy mới.</li><li>As an operator, I want mỗi agent/collector có credential riêng và phạm vi ghi riêng, so that một collector không thể sửa kết quả của đối tượng khác.</li><li>As an operator, I want agent và worker tự khởi động, chạy định kỳ và không chờ UI, so that việc giám sát không phụ thuộc ADMIN mở trang.</li><li>As an operator, I want lỗi hoặc timeout một probe không chặn các probe khác và heartbeat, so that collector vẫn hoạt động khi một thành phần lỗi.</li><li>As an operator, I want request lặp hoặc kết quả đến trễ không làm mới dữ liệu cũ, so that trạng thái dựa trên phép đo thực tế gần nhất.</li><li>As an operator, I want probe chỉ đọc và không gây publish, gửi email hoặc phát sinh chi phí AI, so that giám sát không làm thay đổi nghiệp vụ.</li><li>As an operator, I want secret, response nghiệp vụ và thông tin kết nối không xuất hiện trên dashboard/log, so that công cụ giám sát không làm lộ dữ liệu.</li><li>As an operator, I want kiểm tra nội bộ không yêu cầu public port từng service/database, so that triển khai monitoring phù hợp mạng hiện có.</li><li>As an ADMIN, I want thông báo rõ khi chính backend giám sát không truy cập được, so that tôi không hiểu nhầm tất cả server/service đều Offline hoặc DOWN.</li></ol><h2 id="implementation-decisions" tabindex="-1">Implementation Decisions <a class="header-anchor" href="#implementation-decisions" aria-label="Permalink to &quot;Implementation Decisions&quot;">​</a></h2><h3 id="pham-vi-đo-va-thuat-ngu" tabindex="-1">Phạm vi đo và thuật ngữ <a class="header-anchor" href="#pham-vi-đo-va-thuat-ngu" aria-label="Permalink to &quot;Phạm vi đo và thuật ngữ&quot;">​</a></h3><ul><li><strong>Server/host:</strong> máy EC2/VPS thực tế; một agent tài nguyên trên mỗi host. CPU/RAM toàn host không được sao chép thành tài nguyên riêng từng repo/container.</li><li><strong>Health target:</strong> đối tượng được khai báo thuộc một trong bốn loại SERVICE, CONTAINER, DATABASE, ENDPOINT. Mỗi instance có target riêng; endpoint qua load balancer không đại diện health từng replica.</li><li><strong>Collector:</strong> nguồn thực hiện probe, được phân công target cụ thể. Một target có một collector chủ động; probe nội bộ và probe qua Gateway là hai target khác nhau.</li><li><strong>System ADMIN:</strong> quyền toàn hệ thống BrandHub, khác OWNER/MANAGER/MEMBER tại workspace. Kiểm tra ở backend, không chỉ ẩn menu.</li><li><strong>Online/Offline:</strong> trạng thái liên lạc heartbeat host. <strong>UP/DOWN/UNKNOWN:</strong> kết quả health của target. Hai lớp không suy ra lẫn nhau.</li></ul><h3 id="cac-module-va-trach-nhiem" tabindex="-1">Các module và trách nhiệm <a class="header-anchor" href="#cac-module-va-trach-nhiem" aria-label="Permalink to &quot;Các module và trách nhiệm&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Thành phần</th><th>Quyết định</th></tr></thead><tbody><tr><td>BrandHub Web</td><td>Một trang admin, hai tab, bộ lọc, panel thông tin và polling</td></tr><tr><td>API Gateway</td><td>Route monitoring, phân biệt xác thực JWT người dùng với agent/collector token</td></tr><tr><td>Business Service</td><td>Module monitoring xác thực, nhận heartbeat/kết quả, lưu dữ liệu và cung cấp API đọc</td></tr><tr><td>DB của Business</td><td>Đề xuất PostgreSQL qua JPA; không cần thêm DB chuyên dụng cho phạm vi hiện tại</td></tr><tr><td>Host agent</td><td>Đọc tài nguyên toàn máy, chạy bằng trình quản lý tiến trình như systemd</td></tr><tr><td>Probe worker</td><td>Scheduler nền trên mạng truy cập được target, không chạy trong request GET của ADMIN</td></tr><tr><td>Container collector</td><td>Đọc runtime và health metadata trên đúng host, giới hạn quyền đọc cần thiết</td></tr><tr><td>Infrastructure/deployment</td><td>Khai báo danh mục, cấu hình network/secret, cài agent/worker và cấp credential</td></tr><tr><td>Các service ứng dụng</td><td>Cung cấp hoặc xác minh health/readiness và assertion tương ứng; không nhúng collector tài nguyên host vào từng repo</td></tr></tbody></table><p>Tái sử dụng ý tưởng collector tài nguyên và UI từ VPS Monitor; không mang sang cơ chế đăng ký agent công khai, quản lý tài khoản riêng, lưu toàn bộ Metric hoặc Telegram. Các endpoint/schema trong đặc tả là hợp đồng mục tiêu, chưa phải chức năng có sẵn của BrandHub.</p><h3 id="host-metrics-va-heartbeat" tabindex="-1">Host metrics và heartbeat <a class="header-anchor" href="#host-metrics-va-heartbeat" aria-label="Permalink to &quot;Host metrics và heartbeat&quot;">​</a></h3><ul><li>Agent gửi theo chu kỳ mục tiêu 15 giây; chu kỳ thực tế có thể cộng thời gian xử lý/mạng. Không gửi chồng heartbeat hoặc replay backlog.</li><li>CPU tính từ chênh lệch bộ đếm CPU toàn host giữa hai lần đo, phần idle gồm iowait. RAM bằng phần MemTotal trừ MemAvailable chia MemTotal. Disk đo used/total tại filesystem gắn ở <code>/</code>. Uptime tính từ lúc host khởi động, không phải uptime container.</li><li>Phần trăm hữu hạn trong khoảng 0–100; uptime nguyên không âm. Trường chỉ số phải có mặt nhưng cho phép null khi không đọc được; UI hiển thị “—”, không giả lập 0.</li><li>Backend gán lastSeenAt khi nhận heartbeat hợp lệ và cập nhật nguyên tử với mẫu mới nhất. Token/payload sai không thay đổi thời điểm này.</li><li>Chưa có heartbeat: NO_DATA. Tuổi heartbeat không quá 60 giây: ONLINE. Quá 60 giây: OFFLINE. Đúng 60 giây vẫn ONLINE; tính theo đồng hồ backend tại lúc đọc API.</li><li>Offline giữ mẫu cuối có nhãn cũ; heartbeat hợp lệ mới đưa host về Online. Không lưu status host thành giá trị cố định trong DB.</li></ul><h3 id="probe-va-hop-đong-kiem-tra" tabindex="-1">Probe và hợp đồng kiểm tra <a class="header-anchor" href="#probe-va-hop-đong-kiem-tra" aria-label="Permalink to &quot;Probe và hợp đồng kiểm tra&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Loại</th><th>Thành công</th><th>Giới hạn ý nghĩa</th></tr></thead><tbody><tr><td>SERVICE</td><td>HTTP status và JSON khớp hợp đồng của đúng instance</td><td>Ghi checkScope là READINESS hoặc LIVENESS theo thực tế; không gọi liveness là readiness</td></tr><tr><td>CONTAINER</td><td>Runtime running và Docker health healthy</td><td>Running không có healthcheck là UNKNOWN về health ứng dụng</td></tr><tr><td>DATABASE</td><td>Kết nối xác thực và ping/truy vấn nhẹ thành công trong timeout</td><td>Cổng TCP mở không đủ chứng minh database hoạt động</td></tr><tr><td>ENDPOINT</td><td>GET được cho phép, status và assertion nội dung đúng</td><td>Chỉ chứng minh luồng đọc đã chọn, không chứng minh toàn bộ nghiệp vụ</td></tr></tbody></table><ul><li>Probe mặc định mỗi 30 giây, timeout tổng kết nối/đọc 5 giây, tối đa 5 probe đồng thời, không chồng lần chạy cùng target. Tham số cấu hình được theo target; vòng quét phải phù hợp ngưỡng stale.</li><li>Kết quả thất bại hợp lệ đầu tiên đổi DOWN ngay; lần PASS tiếp theo đổi UP. Không có debounce hay đếm nhiều lần lỗi trong bản này.</li><li>Host/collector heartbeat độc lập với scheduler probe. Worker vẫn chạy khi UI đóng; một target timeout không chặn các target khác.</li><li>Truy vấn DB dùng thao tác nhẹ: PostgreSQL chọn hằng số, MongoDB ping, Redis PING, Neo4j trả hằng số. ChromaDB và RabbitMQ dùng endpoint/health API phù hợp phiên bản deploy, phải xác minh trước khi cấu hình.</li><li>Gateway, Business và Publisher tham chiếu Actuator health hiện có; AI tham chiếu health endpoint hiện có. Phải xác minh payload, auth, dependency và checkScope trước khi bật target.</li><li>CloudFront/frontend có thể là ENDPOINT, không có metrics host giả. MongoDB Atlas có thể là DATABASE, không cài Bash agent lên hạ tầng managed. Mobile app không phải host giám sát.</li><li>Endpoint nghiệp vụ là các API GET thật được người vận hành chọn, dùng tài khoản đọc riêng và assertion tối thiểu. Không tự phát minh route hoặc chạy tác vụ publish/gửi email/thanh toán/AI có phí.</li></ul><h3 id="quy-tac-trang-thai-health" tabindex="-1">Quy tắc trạng thái health <a class="header-anchor" href="#quy-tac-trang-thai-health" aria-label="Permalink to &quot;Quy tắc trạng thái health&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Tình huống</th><th>Trạng thái</th></tr></thead><tbody><tr><td>Mẫu còn mới, collector còn liên lạc và phép kiểm tra thành công</td><td>UP</td></tr><tr><td>Mẫu còn mới, kiểm tra đã thực hiện nhưng target timeout/từ chối kết nối/status hoặc body sai/truy vấn lỗi</td><td>DOWN</td></tr><tr><td>Chưa có mẫu, mẫu stale, collector mất liên lạc, không thực hiện được phép kiểm tra hoặc thiếu cấu hình</td><td>UNKNOWN</td></tr><tr><td>HTTP 401/403 hoặc DB từ chối credential probe</td><td>UNKNOWN với PROBE_AUTH_FAILED</td></tr><tr><td>Container running nhưng unhealthy</td><td>DOWN</td></tr><tr><td>Container restarting, exited, dead hoặc paused</td><td>DOWN</td></tr><tr><td>Container starting hoặc running chưa có healthcheck</td><td>UNKNOWN với STARTING hoặc NO_HEALTHCHECK</td></tr><tr><td>Runtime truy cập được nhưng không thấy container khớp selector đã khai báo</td><td>DOWN với CONTAINER_NOT_FOUND; không tự xóa target</td></tr><tr><td>Không đọc được runtime hoặc selector khớp nhiều container ngoài thiết kế</td><td>UNKNOWN với lỗi collector/cấu hình</td></tr></tbody></table><ul><li>Collector heartbeat mỗi 15 giây; quá 60 giây không nhận hoặc chưa từng nhận thì target của collector là UNKNOWN. Heartbeat collector không cập nhật checkedAt của probe.</li><li>Mẫu health quá 90 giây từ checkedAt là UNKNOWN/STALE dù collector vẫn heartbeat. Đúng 90 giây chưa stale. Không gán stale chỉ theo receivedAt.</li><li>Giữ lastKnownStatus và thời điểm để hiển thị kết quả cũ; không gọi kết quả cũ là trạng thái hiện tại. Collector lỗi chỉ ảnh hưởng target thuộc collector đó.</li><li>Host Offline không tự đổi mọi target DOWN. Probe độc lập từ nguồn còn hoạt động vẫn được đánh giá theo bằng chứng riêng. CPU/RAM cao không tự đổi health.</li><li>DOWN là lỗi từ góc nhìn probe và phạm vi đã cấu hình; không chứng minh máy vật lý tắt hoặc xác định nguyên nhân gốc.</li><li>Nếu hiển thị tổng hợp service: tất cả UP → UP; tất cả DOWN → DOWN; có UP và DOWN → DEGRADED; có bất kỳ UNKNOWN → UNKNOWN kèm số lượng từng trạng thái. Luôn giữ khả năng xem từng instance; nhóm chưa có instance là UNKNOWN.</li></ul><h3 id="mo-hinh-du-lieu" tabindex="-1">Mô hình dữ liệu <a class="header-anchor" href="#mo-hinh-du-lieu" aria-label="Permalink to &quot;Mô hình dữ liệu&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Thực thể</th><th>Dữ liệu và ràng buộc</th></tr></thead><tbody><tr><td>Server</td><td>serverId unique, name, ipAddress, environment, deployedServices, agentTokenHash, cpuPercent/ramPercent/diskPercent/uptimeSeconds nullable, lastSeenAt nullable</td></tr><tr><td>Collector</td><td>collectorId unique, serverId nullable, tokenHash, lastSeenAt, danh sách target được phép báo cáo</td></tr><tr><td>HealthTarget</td><td>targetId unique, name, kind, environment, serverId nullable, serviceName/instanceId tùy chọn, collectorId, checkScope, probeType, địa chỉ/selector, assertion, credentialRef và các ngưỡng</td></tr><tr><td>HealthResult</td><td>Một mẫu mới nhất mỗi target: checkId, outcome PASS/FAIL/ERROR, checkedAt, receivedAt, latencyMs, reasonCode, httpStatus, runtimeState/runtimeHealth nếu áp dụng</td></tr></tbody></table><ul><li>ID host không dùng repo/container ID/IP làm định danh. Redeploy cùng host giữ ID; thay máy cấp ID mới. Metadata và ánh xạ service do người vận hành cập nhật, không bị heartbeat ghi đè.</li><li>Danh mục host/target luôn tồn tại độc lập với dữ liệu đo để thấy đối tượng chưa có mẫu hoặc container đã mất.</li><li>HealthResult và timestamp cập nhật nguyên tử; chỉ nhận từ collector được phân công. PASS tương ứng kiểm tra thành công, FAIL tương ứng lỗi target, ERROR tương ứng không đánh giá được target; backend kiểm tra tính nhất quán với reasonCode/type rồi tính status.</li><li>Lưu UTC. checkedAt do collector ghi nhận lúc hoàn tất probe; receivedAt do backend gán. Đồng bộ đồng hồ collector. Mặc định từ chối phép đo quá 10 giây trong tương lai hoặc quá 90 giây trong quá khứ; khi cấu hình ngưỡng phải đồng bộ cửa sổ tiếp nhận với staleAfterSeconds. Tuổi mẫu tương lai trong dung sai được chặn tối thiểu 0.</li><li>Request lặp đúng checkId của mẫu hiện tại không thay đổi dữ liệu/thời gian. Kết quả checkedAt cũ hơn mẫu đã lưu bị từ chối; cùng thời điểm nhưng checkId khác bị coi xung đột thay vì ghi đè tùy ý. Không cần lưu lịch sử checkId vô hạn: replay mẫu trước phải bị loại theo thứ tự thời gian.</li><li>Chỉ lưu metadata kết quả chuẩn hóa; không lưu raw response body hoặc credential vào mẫu. credentialRef trỏ tới secret được quản lý, không trả ra UI.</li></ul><h3 id="hop-đong-api-muc-tieu" tabindex="-1">Hợp đồng API mục tiêu <a class="header-anchor" href="#hop-đong-api-muc-tieu" aria-label="Permalink to &quot;Hợp đồng API mục tiêu&quot;">​</a></h3><p>Giữ convention prefix/response của BrandHub khi triển khai; nếu thay đường dẫn đề xuất phải cập nhật đồng bộ frontend và collector.</p><table tabindex="0"><thead><tr><th>Method và endpoint</th><th>Xác thực</th><th>Đầu vào / đầu ra</th></tr></thead><tbody><tr><td>POST <code>/api/monitoring/heartbeat</code></td><td>Bearer token của đúng server</td><td>serverId và các chỉ số bắt buộc, cho phép null; lưu mẫu host mới nhất</td></tr><tr><td>GET <code>/api/monitoring/servers</code></td><td>System ADMIN</td><td>serverTime và servers, gồm metadata, status, chỉ số, lastSeenAt; sắp xếp tên rồi ID</td></tr><tr><td>POST <code>/api/monitoring/collectors/heartbeat</code></td><td>Bearer token của đúng collector</td><td>collectorId; chỉ cập nhật lastSeenAt collector</td></tr><tr><td>POST <code>/api/monitoring/health-results</code></td><td>Bearer collector token</td><td>targetId, checkId, checkedAt, outcome; reasonCode bắt buộc với FAIL/ERROR; metadata kết quả tùy loại</td></tr><tr><td>GET <code>/api/monitoring/health-targets</code></td><td>System ADMIN</td><td>serverTime và targets; lọc environment/serverId/kind/status; gồm scope, instance, collector, trạng thái và kết quả gần nhất</td></tr></tbody></table><ul><li>Danh sách trả cả đối tượng chưa có dữ liệu; danh mục rỗng trả 200 với mảng rỗng. Trường không có/không áp dụng là null.</li><li>API ghi chỉ cập nhật danh mục có sẵn, không tự tạo host/target hoặc nhận URL/credential tùy ý từ kết quả collector.</li><li>API ghi trả 200 khi lưu thành công; retry mẫu hiện tại trả 200 với dấu duplicate và không làm mới timestamp.</li><li>400: payload/filter/timestamp sai. 401: thiếu/sai credential hoặc JWT không hợp lệ. 403: user không phải system ADMIN hoặc collector ghi target ngoài quyền. 404: target không tồn tại. 409: mẫu cũ hoặc xung đột thứ tự. 503: không đọc/ghi được dữ liệu monitoring. Heartbeat host không khớp token/server trả 401.</li><li>Tỷ lệ chỉ số hữu hạn 0–100, uptime nguyên không âm, latency hữu hạn không âm, HTTP status hợp lệ; runtime metadata chỉ áp dụng CONTAINER. Backend kiểm tra outcome và reasonCode phù hợp probe, không chấp nhận status hiển thị tùy ý từ client.</li><li>Không trả token/tokenHash, URL chứa bí mật, cấu hình truy cập DB hoặc raw response qua API ADMIN.</li></ul><h3 id="giao-dien-va-loi-nguon-du-lieu" tabindex="-1">Giao diện và lỗi nguồn dữ liệu <a class="header-anchor" href="#giao-dien-va-loi-nguon-du-lieu" aria-label="Permalink to &quot;Giao diện và lỗi nguồn dữ liệu&quot;">​</a></h3><ul><li>Tải dữ liệu khi mở trang, polling 5 giây khi trang hoạt động; dừng polling khi rời trang. Chu kỳ polling không biến mẫu probe thành dữ liệu tức thời.</li><li>Hiển thị phần trăm một chữ số thập phân, uptime ngày/giờ/phút; timestamp theo múi giờ trình duyệt, phép tính freshness vẫn ở backend.</li><li>Trạng thái có cả chữ và màu. Có loading, danh mục rỗng, chưa có mẫu, stale và lỗi tải riêng cho từng tab/bảng.</li><li>Khi API lỗi, giữ kết quả trước nếu còn quyền, kèm cảnh báo Không thể cập nhật và thời điểm tải thành công cuối; không đổi toàn bộ host thành Offline hoặc target thành DOWN.</li><li>Khi nhận 401/403, dừng tải, xóa dữ liệu bảo vệ khỏi màn hình và dùng luồng đăng nhập/thiếu quyền hiện có; không giữ cache nhạy cảm như một lỗi mạng thông thường.</li></ul><h3 id="quyen-truy-cap-va-van-hanh" tabindex="-1">Quyền truy cập và vận hành <a class="header-anchor" href="#quyen-truy-cap-va-van-hanh" aria-label="Permalink to &quot;Quyền truy cập và vận hành&quot;">​</a></h3><ul><li>Dùng HTTPS cho heartbeat/kết quả và đường truy cập ADMIN. Token ngẫu nhiên riêng từng agent/collector, backend lưu hash; không dùng JWT ADMIN hoặc internal service key chung làm credential collector.</li><li>Gateway cần tách đường xác thực machine credential khỏi JWT người dùng; backend vẫn kiểm tra credential và quyền sở hữu target trước khi lưu.</li><li>Chỉ probe danh mục được cấu hình trước, giới hạn host/port/path; không tự theo redirect ra ngoài danh mục. Không public port nội bộ chỉ để monitoring truy cập.</li><li>HTTP probe dùng GET, response tối đa 64 KiB, không lưu body; vượt giới hạn không được PASS. Tài khoản DB/endpoint có quyền tối thiểu cho kiểm tra đọc.</li><li>Không cấp Docker socket cho Business/Web. Container collector dùng quyền đọc giới hạn; mount socket với cờ chỉ đọc không tự hạn chế quyền Docker API. Nếu dùng proxy runtime phải giới hạn API được gọi, chặn thao tác ghi.</li><li>Log và UI dùng reasonCode/thông báo chuẩn hóa, không đưa token, mật khẩu, connection string, response nghiệp vụ hoặc stack trace nhạy cảm ra ngoài.</li></ul><h2 id="testing-decisions" tabindex="-1">Testing Decisions <a class="header-anchor" href="#testing-decisions" aria-label="Permalink to &quot;Testing Decisions&quot;">​</a></h2><p>Người dùng đã xác nhận phạm vi kiểm thử: API monitoring là ranh giới chính, bổ sung adapter probe và một luồng UI ADMIN. Đây là kế hoạch đã chốt, chưa phải các test đã viết hoặc đã chạy.</p><h3 id="ranh-gioi-kiem-thu" tabindex="-1">Ranh giới kiểm thử <a class="header-anchor" href="#ranh-gioi-kiem-thu" aria-label="Permalink to &quot;Ranh giới kiểm thử&quot;">​</a></h3><ol><li><strong>Ranh giới chính — API monitoring:</strong> gửi heartbeat/kết quả với credential thực của môi trường test, rồi đọc qua API ADMIN và quan sát response. Kiểm tra authorization, validation, lưu mẫu, thứ tự, freshness và trạng thái qua hành vi công khai; ưu tiên integration test với persistence thật được cô lập và đồng hồ điều khiển được. Không assert thứ tự gọi repository, tên private method hoặc chi tiết framework.</li><li><strong>Ranh giới phụ — adapter probe:</strong> chạy probe với HTTP/DB/runtime fixture được kiểm soát, xác minh kết quả chuẩn hóa và timeout. Cần ranh giới này vì chỉ POST kết quả giả vào API không chứng minh collector đo đúng. Dùng DB test tạm thời cho kết nối/truy vấn, fixture cho runtime; smoke test có Docker trên môi trường phù hợp để kiểm chứng adapter runtime.</li><li><strong>Luồng UI ADMIN:</strong> một kịch bản end-to-end chính cho đăng nhập, hai tab, lọc, cập nhật dữ liệu, lỗi một nguồn và mất quyền. Không dùng snapshot toàn trang hoặc assert cấu trúc component để thay thế hành vi người dùng.</li></ol><h3 id="nen-tang-kiem-thu-đa-thay" tabindex="-1">Nền tảng kiểm thử đã thấy <a class="header-anchor" href="#nen-tang-kiem-thu-đa-thay" aria-label="Permalink to &quot;Nền tảng kiểm thử đã thấy&quot;">​</a></h3><ul><li>BrandHub Gateway có integration test Spring Boot trên cổng ngẫu nhiên bằng WebTestClient, kiểm tra HTTP và body Actuator. Đây là tiền lệ cho API test; chưa phải test monitoring và có dependency health được tắt trong cấu hình test hiện có.</li><li>BrandHub Business có JUnit/Mockito/AssertJ test cho RequireRoleAspect, phân biệt system ADMIN và workspace role. Tái sử dụng vocabulary và fixtures xác thực khi phù hợp; kiểm tra API mới vẫn phải chứng minh từ chối OWNER/MANAGER.</li><li>VPS Monitor hiện có script lint/build nhưng chưa có test script trong manifest đã đọc. Không coi nó là bộ kiểm thử sẵn cho collector/monitoring mới.</li><li>Chưa xác minh framework E2E của BrandHub Web; chọn theo công cụ thực tế của repo khi triển khai, không mặc định đã có một bộ test.</li></ul><h3 id="ma-tran-nghiem-thu" tabindex="-1">Ma trận nghiệm thu <a class="header-anchor" href="#ma-tran-nghiem-thu" aria-label="Permalink to &quot;Ma trận nghiệm thu&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Nhóm</th><th>Hành vi bắt buộc kiểm chứng</th></tr></thead><tbody><tr><td>Quyền người dùng</td><td>401 khi thiếu/hết hạn phiên; 403 khi không phải system ADMIN, kể cả OWNER/MANAGER; ADMIN đọc thành công; thu hồi quyền dừng hiển thị dữ liệu</td></tr><tr><td>Quyền machine</td><td>Token sai không ghi dữ liệu; collector không ghi target người khác; không tự đăng ký host/target; response/log không chứa secret</td></tr><tr><td>Host metrics</td><td>Null không bị đổi thành 0; tỷ lệ ngoài 0–100, thiếu trường, uptime âm bị từ chối và không cập nhật lastSeenAt</td></tr><tr><td>Host freshness</td><td>Chưa có heartbeat là NO_DATA; đúng 60 giây ONLINE, lớn hơn 60 OFFLINE; giữ mẫu cũ có nhãn; heartbeat mới phục hồi</td></tr><tr><td>Deployment</td><td>Nhiều repo cùng host có một bộ metrics; nhiều host có ID riêng; redeploy container không sinh host mới; managed target không có CPU/RAM giả</td></tr><tr><td>Service probe</td><td>Status/body đúng là PASS; 200 với body sai thất bại; timeout một target không chặn heartbeat hoặc target khác; probe thành công sau lỗi phục hồi UP</td></tr><tr><td>Container</td><td>Running/healthy UP; running/unhealthy DOWN; thiếu healthcheck hoặc starting UNKNOWN; stopped/mất container DOWN; runtime không đọc được UNKNOWN</td></tr><tr><td>Database</td><td>Thực hiện kết nối và query thật; không chấp nhận TCP mở là đủ; sai credential UNKNOWN; query lỗi phân loại theo reasonCode</td></tr><tr><td>Freshness health</td><td>Collector quá 60 giây hoặc chưa có heartbeat → UNKNOWN; mẫu đúng 90 giây còn mới, quá 90 → STALE; heartbeat collector không làm mới mẫu</td></tr><tr><td>Thứ tự mẫu</td><td>Retry cùng mẫu không đổi timestamp; mẫu cũ hoặc xung đột không ghi đè; quá dung sai đồng hồ bị từ chối; không replay backlog</td></tr><tr><td>Replica</td><td>Kiểm tra từng instance; UP + DOWN thành DEGRADED nếu tổng hợp; bất kỳ UNKNOWN làm tổng UNKNOWN; host Online không che service DOWN</td></tr><tr><td>UI và nguồn lỗi</td><td>Polling và filter đúng; host API/health API lỗi độc lập; báo không thể cập nhật thay vì suy mọi đối tượng hỏng; bảng rỗng/loading/stale rõ ràng</td></tr><tr><td>Vận hành probe</td><td>Chạy khi UI đóng; không probe chồng cùng target; concurrency/timeout hoạt động; URL/redirect ngoài cấu hình bị chặn; response quá lớn không PASS</td></tr><tr><td>An toàn nghiệp vụ</td><td>Chỉ GET đã khai báo, xác thực body; không publish/gửi email/thanh toán/call AI tính phí; không lộ dữ liệu thật trong test</td></tr></tbody></table><p>Không dùng sleep dài để kiểm tra mốc 60/90 giây; điều khiển đồng hồ tại ranh giới phù hợp. Test trên fixture hoặc môi trường cô lập, không tắt service production để thử. Đây là kế hoạch nghiệm thu, không phải báo cáo test đã pass.</p><h2 id="out-of-scope" tabindex="-1">Out of Scope <a class="header-anchor" href="#out-of-scope" aria-label="Permalink to &quot;Out of Scope&quot;">​</a></h2><ul><li>CPU/RAM từng container/service, distributed tracing, tổng hợp log và xác định nguyên nhân gốc tự động.</li><li>Lưu toàn bộ mẫu, biểu đồ lịch sử, báo cáo, dự báo, cảnh báo Telegram/email và thông báo phục hồi.</li><li>SSH, terminal, reboot, restart container, điều khiển server hoặc thay đổi nghiệp vụ từ dashboard.</li><li>Đăng ký agent công khai; UI thêm/xóa host, nhập URL tùy ý, quản lý tags hoặc installer tự động.</li><li>Xây dựng lại đăng nhập/đăng ký/phân quyền; monitoring sử dụng cơ chế BrandHub hiện có.</li><li>Probe nghiệp vụ có tác dụng ghi, kiểm tra toàn bộ giao dịch đầu-cuối hoặc tác vụ phát sinh chi phí.</li><li>Đo tài nguyên hạ tầng S3/CloudFront/Atlas bằng Bash agent; thiết bị chạy mobile app.</li><li>Cam kết dashboard tiếp tục hoạt động khi chính Gateway/Business/DB phục vụ monitoring sập. Khả năng đó cần kiến trúc độc lập bổ sung.</li></ul><h2 id="further-notes" tabindex="-1">Further Notes <a class="header-anchor" href="#further-notes" aria-label="Permalink to &quot;Further Notes&quot;">​</a></h2><h3 id="gioi-han-deployment" tabindex="-1">Giới hạn deployment <a class="header-anchor" href="#gioi-han-deployment" aria-label="Permalink to &quot;Giới hạn deployment&quot;">​</a></h3><p>Cấu hình production đã đọc mô tả một Compose stack gồm Nginx, Gateway, Business, AI, Publisher và dịch vụ dữ liệu; frontend được mô tả trên S3/CloudFront, MongoDB Atlas bên ngoài. Bộ công cụ deployment khác có chuẩn bị EC2 Amazon Linux nhưng chưa chứng minh topology thực tế. Chưa kết nối máy triển khai để xác nhận số host, số replica hoặc endpoint hoạt động.</p><p>Nếu monitoring cùng host với backend, khi host đó tắt thì API giám sát cũng mất. UI chỉ báo không thể cập nhật; muốn ADMIN vẫn quan sát được sự cố đó phải có backend lưu/đọc, đường truy cập và xác thực độc lập. Chỉ tách collector hoặc DB ra ngoài không đủ nếu API đọc vẫn đi qua Gateway/Business đã ngừng hoạt động.</p><h3 id="chuan-bi-khi-trien-khai" tabindex="-1">Chuẩn bị khi triển khai <a class="header-anchor" href="#chuan-bi-khi-trien-khai" aria-label="Permalink to &quot;Chuẩn bị khi triển khai&quot;">​</a></h3><p>Người vận hành phải cung cấp danh mục host/môi trường, ánh xạ instance, container selector, hợp đồng health thực tế, credential đọc và endpoint nghiệp vụ GET được chọn. Đây là cấu hình môi trường cần điền, không phải lý do tự thêm endpoint hoặc giả dữ liệu. Không bật target chưa xác minh contract/credential.</p><p>Phải kiểm tra glossary và ADR áp dụng của từng repo khi bắt đầu code. Glossary BrandHub đã đọc phân biệt workspace role và thực thể nghiệp vụ nhưng chưa định nghĩa đầy đủ mô hình monitoring; các tên Server, Collector, HealthTarget, HealthResult ở trên là mô hình đề xuất. Không có ADR monitoring được xác nhận trong lượt rà soát này.</p><h3 id="trang-thai-tai-lieu-va-phat-hanh" tabindex="-1">Trạng thái tài liệu và phát hành <a class="header-anchor" href="#trang-thai-tai-lieu-va-phat-hanh" aria-label="Permalink to &quot;Trạng thái tài liệu và phát hành&quot;">​</a></h3><p>Bản này đã bao gồm host monitoring và health từng thành phần, thay thế cấu trúc đặc tả tích lũy trước đó bằng mẫu to-spec. Vẫn chưa gồm lịch sử và tài nguyên riêng từng service như các ý tưởng mở rộng trong draft BrandHub. DA-1013 đã có implementation tại Business, Gateway, Web và Infrastructure; trạng thái kiểm chứng được ghi riêng trong evidence.md. Chưa nghiệm thu deployment thực tế.</p><p>Theo lựa chọn rõ ràng của người dùng, chỉ lưu bản spec local; không tạo issue, cấu hình tracker hoặc áp dụng nhãn triage. Bước publish mặc định của skill to-spec không áp dụng cho yêu cầu này. Phạm vi tính năng hướng tới BrandHub; repository VPS Monitor là nguồn tham khảo implementation.</p><h3 id="hop-đong-implementation-da-1013" tabindex="-1">Hợp đồng implementation DA-1013 <a class="header-anchor" href="#hop-đong-implementation-da-1013" aria-label="Permalink to &quot;Hợp đồng implementation DA-1013&quot;">​</a></h3><p>Hai API đọc dùng phân trang page/size (tối đa 200), trả totalPages và serverTime. Frontend đọc đủ các trang trước khi thay snapshot. Bộ lọc status được tính sau freshness trên từng trang; totalPages phản ánh danh mục, không phải tổng kết quả sau lọc status. Không dùng số phần tử trang để quyết định đã hết danh mục.</p><p>Worker dùng cấu hình operator để giới hạn chính xác URL/selector, không nhận URL từ người dùng dashboard. Không tự đăng ký host hoặc tạo target production. Target chưa xác minh endpoint/credential không được bật chỉ để làm dashboard có dữ liệu.</p>',62)])])}const m=n(a,[["render",c]]);export{u as __pageData,m as default};
